async def act(page):
    import re
    import asyncio

    # Small delay to allow transient UI to settle
    await asyncio.sleep(0.25)

    # 1) Locate the complementary region
    comp_locator = page.get_by_role("complementary")
    if await comp_locator.count() == 0:
        # Nothing to do if no complementary region
        return
    comp = comp_locator.nth(0)

    # 2) Locate the nested search region if present
    search_region = comp
    if await comp.get_by_role("search").count() > 0:
        search_region = comp.get_by_role("search").nth(0)

    # 3) Locate the accessible search input: prefer searchbox named "Search", then any searchbox, then textbox
    searchbox = None
    if await search_region.get_by_role("searchbox", name="Search").count() > 0:
        searchbox = search_region.get_by_role("searchbox", name="Search").nth(0)
    elif await search_region.get_by_role("searchbox").count() > 0:
        searchbox = search_region.get_by_role("searchbox").nth(0)
    elif await search_region.get_by_role("textbox").count() > 0:
        searchbox = search_region.get_by_role("textbox").nth(0)

    # 4) Fill the search term 'Collector'
    if searchbox is not None:
        try:
            await searchbox.fill("Collector")
        except Exception:
            try:
                await searchbox.focus()
                await page.keyboard.type("Collector")
            except Exception:
                pass

    # 5) Trigger the search: prefer clicking the search button inside the search region
    clicked_search = False
    try:
        if await search_region.get_by_role("button", name=re.compile(r"search", re.I)).count() > 0:
            btn = search_region.get_by_role("button", name=re.compile(r"search", re.I)).nth(0)
            await btn.click()
            clicked_search = True
    except Exception:
        clicked_search = False

    # Fallback: click first button inside complementary region
    if not clicked_search:
        try:
            if await comp.get_by_role("button").count() > 0:
                await comp.get_by_role("button").nth(0).click()
                clicked_search = True
        except Exception:
            clicked_search = False

    # Final fallback: press Enter in the searchbox
    if not clicked_search and searchbox is not None:
        try:
            await searchbox.press("Enter")
            clicked_search = True
        except Exception:
            try:
                await page.keyboard.press("Enter")
                clicked_search = True
            except Exception:
                clicked_search = False

    # 6) Wait for results to appear in role='main'
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=3000)
    except Exception:
        await asyncio.sleep(0.8)

    # 7) Click the first result: main -> article (first) -> heading (level=2) -> link
    main_locator = page.get_by_role("main")
    if await main_locator.count() == 0:
        return
    main = main_locator.nth(0)

    articles_locator = main.get_by_role("article")
    if await articles_locator.count() == 0:
        # No articles found; nothing more to do
        return

    first_article = articles_locator.nth(0)

    # Prefer heading(level=2) -> link path
    if await first_article.get_by_role("heading", level=2).count() > 0:
        heading = first_article.get_by_role("heading", level=2).nth(0)
        if await heading.get_by_role("link").count() > 0:
            await heading.get_by_role("link").nth(0).click()
            return

    # Fallback: click first link inside the article
    if await first_article.get_by_role("link").count() > 0:
        await first_article.get_by_role("link").nth(0).click()
        return

    # If we reach here, nothing was clickable
    return

